#include <rclcpp/rclcpp.hpp>
#include <nav_msgs/msg/odometry.hpp>
#include <quadrotor_msgs/msg/position_command.hpp>
#include <quadrotor_msgs/msg/so3_command.hpp>
#include <so3_control/SO3Control.h>
#include <Eigen/Geometry>
class SO3Node:public rclcpp::Node{public:SO3Node():Node("so3_control"){kx_=Eigen::Vector3d(4,4,4);kv_=Eigen::Vector3d(2,2,2);pub_=create_publisher<quadrotor_msgs::msg::SO3Command>("/so3_command",10);create_subscription<quadrotor_msgs::msg::PositionCommand>("/position_cmd",10,[this](auto m){cmd_=*m;have_cmd_=true;});create_subscription<nav_msgs::msg::Odometry>("/odom",10,[this](auto m){ctrl_.setPosition({m->pose.pose.position.x,m->pose.pose.position.y,m->pose.pose.position.z});ctrl_.setVelocity({m->twist.twist.linear.x,m->twist.twist.linear.y,m->twist.twist.linear.z});publish();});}private:void publish(){if(!have_cmd_)return;ctrl_.calculateControl({cmd_.position.x,cmd_.position.y,cmd_.position.z},{cmd_.velocity.x,cmd_.velocity.y,cmd_.velocity.z},{cmd_.acceleration.x,cmd_.acceleration.y,cmd_.acceleration.z},cmd_.yaw,cmd_.yaw_dot,kx_,kv_);auto f=ctrl_.getComputedForce();auto q=ctrl_.getComputedOrientation();quadrotor_msgs::msg::SO3Command o;o.header.stamp=get_clock()->now().to_msg();o.force.x=f.x();o.force.y=f.y();o.force.z=f.z();o.orientation.x=q.x();o.orientation.y=q.y();o.orientation.z=q.z();o.orientation.w=q.w();pub_->publish(o);}SO3Control ctrl_;quadrotor_msgs::msg::PositionCommand cmd_;bool have_cmd_=false;Eigen::Vector3d kx_,kv_;rclcpp::Publisher<quadrotor_msgs::msg::SO3Command>::SharedPtr pub_;};int main(int c,char**v){rclcpp::init(c,v);rclcpp::spin(std::make_shared<SO3Node>());rclcpp::shutdown();}
